// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, uint256 value) public {
        vm.assume(target != address(0));
        vm.assume(value > 0 && value <= address(this).balance);

        // Fund the contract
        vm.deal(address(c), 1 ether);

        uint256 balanceBefore = address(c).balance;

        // Call sendMoney
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, target, value));

        uint256 balanceAfter = address(c).balance;

        // If the call succeeded, balance should have decreased by value
        // If the call reverted (because target reverts or in buggy version when _s is true), balance stays same
        // But in reference C, revert only happens when _s is false, so balance decreases by value
        // In buggy M, revert happens when _s is true, so balance stays same when call succeeds
        if (success) {
            assertTrue(balanceAfter == balanceBefore - value, "Balance should decrease by value when call succeeds");
        } else {
            assertTrue(balanceAfter == balanceBefore, "Balance should remain same when call reverts");
        }
    }
}

